  const o = ctx.createOscillator(); o.type = 'triangle'; o.frequency.setValueAtTime(4200 * (0.95 + kit.random() * 0.1), t); o.frequency.exponentialRampToValueAtTime(2100, t + 0.03);
  const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.5, t + 0.001); g.gain.setTargetAtTime(0, t + 0.002, 0.012);
