  const gn = ctx.createGain(); gn.gain.setValueAtTime(0.3, t); gn.gain.setTargetAtTime(0, t + 0.001, 0.004);
  o.connect(g).connect(ctx.destination); n.connect(hp).connect(gn).connect(ctx.destination);
  o.start(t); o.stop(t + 0.08); n.start(t);
